import Foundation

@main
struct BBBikeArchiveSafetyTests {
    static func main() throws {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("bbbike-zip-tests-" + UUID().uuidString)
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let fixtures: [(String, String, Bool)] = [
            ("ZIP64 local header", "", true),
            ("valid", "", true),
            ("duplicate", "", false),
            ("hidden symlink", "", false),
            ("traversal", "", false),
            ("extra IMG", "", false),
            ("expansion cap", "", false),
            ("encrypted", "", false),
            ("local size mismatch", "", false),
            ("IMG size mismatch", "", false)
        ]
        for (index, fixture) in fixtures.enumerated() {
            let url = root.appendingPathComponent("case-\(index).zip")
            try Data(base64Encoded: fixture.1)!.write(to: url)
            var accepted = false
            do {
                try BBBikeArchiveSafety.validate(archiveURL: url,
                    expectedPayloadPath: "andorra-garmin-bbbike-latin1/gmapsupp.img", expectedIMGBytes: 512)
                accepted = true
            } catch { }
            guard accepted == fixture.2 else { fatalError("Unexpected acceptance: \(fixture.0)") }
        }
        print("BBBike archive safety: \(fixtures.count) PASS")
    }
}
